ate Hostels"},{"icon":"ti-bus","name":"Transport Facility"},{"icon":"ti-microscope","name":"Research Facility"},{"icon":"ti-crown","name":"Placement Cell"},{"icon":"ti-heartbeat","name":"Medical Centre"},{"icon":"ti-trophy","name":"Sports Facility"},{"icon":"ti-microphone","name":"Seminar Hall"},{"icon":"ti-restaurant","name":"Cafeteria"},{"icon":"ti-cpu","name":"Smart Classrooms"}],"placementRate":78,"avgPackage":"₹2.8 LPA","highestPackage":"₹4.5 LPA","placementYear":null,"admissionProcess":[{"title":"Register Through University Portal","desc":"Register at the Tamil Nadu Dr. M.G.R. Medical University counselling portal during the announced window for pharmacy admissions."},{"title":"Certificate & Document Verification","desc":"Attend document verification with original HSC mark sheets, community certificate, transfer certificate, and D.Pharm certificate for lateral entry applicants."},{"title":"Merit Rank & Category Allotment","desc":"Seat allotment is based on merit rank, category reservation, and programme/college preferences submitted during counselling."},{"title":"Confirm Allotment & Fee Payment","desc":"Accept the allotted seat and remit fees through the university payment gateway within the stipulated timeframe."},{"title":"Report to Campus & Enrollment","desc":"Report to the JRIPSR campus on the notified joining date with all original documents for formal enrollment."}],"scholarships":["First Graduate Scholarship (Govt. of Tamil Nadu)","BC / MBC Scholarship","SC / ST Scholarship","AICTE Pragati Scholarship for Girls","AICTE Saksham Scholarship for Differently Abled","Merit Scholarship for Academic Excellence","Minority Scholarship","Post Matric Scholarship","Tamil Nadu Chief Minister''s Scholarship","Management Scholarship for Meritorious Students"],"events":["National Pharmacy Week Celebration","Pharmaceutical Sciences Research Symposium","Drug Awareness & Health Camp","Inter-College Sports Meet","Annual Cultural Fest","Community Health Awareness Drives"],