 infrastructure on campus","Excellent residency placement and higher education progression records"],"departments":[{"name":"MBBS - Bachelor of Medicine and Bachelor of Surgery","level":"UG"},{"name":"MD General Medicine","level":"PG"},{"name":"MS General Surgery","level":"PG"},{"name":"MD Paediatrics","level":"PG"},{"name":"MD Radio Diagnosis","level":"PG"},{"name":"MS Orthopaedics","level":"PG"},{"name":"DM Cardiology","level":"PG"},{"name":"M.Ch. Cardiothoracic Surgery","level":"PG"}],"facilities":[{"icon":"ti-wifi","name":"Campus Wi-Fi"},{"icon":"ti-books","name":"Central Library"},{"icon":"ti-desktop","name":"Computer Lab"},{"icon":"ti-blackboard","name":"Smart Classrooms"},{"icon":"ti-home","name":"Hostel"},{"icon":"ti-bus","name":"Transport"},{"icon":"ti-world","name":"Language Lab"},{"icon":"ti-trophy","name":"Sports"},{"icon":"ti-microphone","name":"Seminar Hall"},{"icon":"ti-crown","name":"Placement Cell"},{"icon":"ti-light-bulb","name":"Innovation Cell"},{"icon":"ti-desktop","name":"Digital Learning Centre"}],"placementRate":95,"avgPackage":"12.0 LPA","highestPackage":"24.0 LPA","placementYear":null,"admissionProcess":[{"title":"NEET Qualification","desc":"Candidates must qualify NEET-UG for MBBS or NEET-PG/SS for postgraduate and super-specialty courses."},{"title":"Centralized Counselling","desc":"Participate in MCC or Tamil Nadu state medical counselling conducted by the selection committee."},{"title":"Choice Filling","desc":"Select PSG Institute of Medical Sciences and Research during the option entry phase."},{"title":"Seat Allotment","desc":"Receive provisional allotment based on NEET rank, category, and seat availability."},{"title":"Document Verification & Admission","desc":"Report to the college with original documents and complete fee payment."}],"scholarships":["PSG & Sons'' Charities Merit Scholarship","First Graduate Fee Concession","Government Post-Matric Scholarship","Central Sector Scholarship Scheme","Institutional Research Fellowship","