28303","email":"info@mapims.org","image":"https://collegeshine.com/wp-content/uploads/2026/08/Melmaruvathur-Adhiparasakthi-Institute-of-Medical-Sciences-and-Research-Kancheepuram_74_11zon-288x300.webp","videoUrl":null,"affiliation":"The Tamil Nadu Dr. M.G.R. Medical University, Chennai","accreditation":["National Medical Commission (NMC)","The Tamil Nadu Dr. M.G.R. Medical University","Adhiparasakthi Charitable Medical, Educational and Cultural Trust","Government of Tamil Nadu Recognized"],"about":"Melmaruvathur Adhiparasakthi Institute of Medical Sciences and Research (MAPIMS), founded in 2008, is situated on a sprawling 45.75-acre campus along the Chennai-Trichy National Highway (NH-45) in Chengalpattu district (formerly Kancheepuram). Managed by the Adhiparasakthi Charitable Medical, Educational and Cultural Trust, the institution is affiliated with The Tamil Nadu Dr. M.G.R. Medical University and approved by the National Medical Commission (NMC).\\n\\nThe attached multi-specialty teaching hospital features over 700 beds and handles a high daily outpatient volume, offering comprehensive clinical training across diverse departments. MAPIMS is committed to delivering exceptional medical education, fostering advanced clinical research, and instilling compassionate healthcare values in every student pursuing undergraduate and postgraduate medical degrees.\\n\\nEquipped with state-of-the-art laboratories, an extensive central library, modern lecture theatres, and dedicated residential facilities, MAPIMS creates an ideal atmosphere for intellectual growth and professional development. Graduates from MAPIMS excel in medical practice, research, and postgraduate residencies globally.","highlights":["Approved by National Medical Commission (NMC) and affiliated with TN MGR Medical University","Sprawling 45.75-acre modern campus on Chennai-Trichy National Highway","Multi-specialty teaching hospital with over 700 beds and high patient inflow","Experienced and dedicated faculty members across all medical specialties","Comprehensive undergraduate (MBBS) and postgraduate (MD/MS) programs","Advanced central research lab and well-stocked digital library","Active participation in rural community health and outreach programs","Separate residential hostels with modern amenities for boys and girls","Robust placement and higher residency progression record","Holistic campus environment supporting cultural and sports activities"],"departments":[{"name":"MBBS - Bachelor of Medicine and Bachelor of Surgery","level":"UG"},{"name":"MD General Medicine","level":"PG"},{"name":"MS General Surgery","level":"PG"},{"name":"MD Paediatrics","level":"PG"},{"name":"MD Radio Diagnosis","level":"PG"},{"name":"MS Orthopaedics","level":"PG"},{"name":"MD Anaesthesiology","level":"PG"},{"name":"MD Obstetrics & Gynaecology","level":"PG"}],"facilities":[{"icon":"ti-wifi","name":"Campus Wi-Fi"},{"icon":"ti-books","name":"Central Library"},{"icon":"ti-desktop","name":"Computer Lab"},{"icon":"ti-blackboard","name":"Smart Classrooms"},{"icon":"ti-home","name":"Hostel"},{"icon":"ti-bus","name":"Transport"},{"icon":"ti-world","name":"Language Lab"},{"icon":"ti-trophy","name":"Sports"},{"icon":"ti-microphone","name":"Seminar Hall"},{"icon":"ti-crown","name":"Placement Cell"},{"icon":"ti-light-bulb","name":"Innovation Cell"},{"icon":"ti-desktop","name":"Digital Learning Centre"}],"placementRate":92,"avgPackage":"10.5 LPA","highestPackage":"20.0 LPA","placementYear":null,"admissionProcess":[{"title":"NEET Qualification","desc":"Secure valid scores in NEET-UG for MBBS or NEET-PG for postgraduate medical seats."},{"title":"State/Central Counselling","desc":"Register for counselling conducted by the Selection Committee, Directorate of Medical Education, Chennai."},{"title":"Choice Selection","desc":"Select MAPIMS Melmaruvathur during option entry rounds."},{"title":"Provisional Allotment","desc":"Receive college allotment based on merit rank and category reservation guidelines."},{"title":"Reporting & Verification","desc":"Complete admission formalities by submitting original documents and fee payment."}],"scholarships":["Adhiparasakthi Trust Merit Scholarship","First Graduate Tuition Concession","Government SC/ST Post-Matric Scholarship","BC/MBC Welfare Financial Support","Central Sector Scholarship Scheme","Institutional Research Assistant Stipend","Need-Based Fee Waiver","Ex-Servicemen Ward Grant"],"events":["MAPIMS Annual National Medical Conference","Adhiaura - Inter-Medical Cultural Festival","CME on Clinical Innovations","World Health Day Mega Free Camp","Sports Meet and Athletics Championship","Alumni Homecoming Meet"],"distanceInfo":{"airport":"Chennai International Airport - 75 km","railway":"Melmaruvathur Railway Station - 2 km","bustand":"Melmaruvathur Bus Stand - 1 km","metro":"N/A","hospital":"MAPIMS Hospital - On Campus"},"hostelFeatures":["Separate hostel facilities for men and women with tight security","24-hour backup power supply and solar hot water systems","Hygienic mess serving nutritious South and North Indian meals","Reading rooms and high-speed Wi-Fi connectivity","Indoor sports and gymnasium facilities","24/7 medical emergency support team on site","Regular housekeeping and pest control services","Convenient proximity to college academic blocks and hospital"],"technicalClubs":["MAPIMS Clinical Research Club","Surgical Anatomy Interest Group","Community Medicine Society","Emergency Life Support Guild"],"culturalClubs":["Adhi Music and Dance Club","Dramatic and Literary Society","Fine Arts and Photography Club","Quiz and Debate Forum"],"communityService":["Regular Free Rural Health Camps in Chengalpattu District","Blood Donation Drives in association with Red Cross","Adoption of Local Villages for Healthcare Support","AIDS Awareness and Prevention Rallies","School Health Screening and Vaccination Camps","Environmental Tree Plantation Drives"]}'),
