('immaculate-college-for-women-cuddalore','immaculate-college-for-women-cuddalore','Immaculate College for Women','ICW','arts-science','Arts and Science College for Women','Private Unaided (Catholic Minority Institution)','2014','Chinnakanganankuppam, Cuddalore - 607006','Cuddalore','L.S. Dupuis Street, Chinnakanganankuppam, Cuddalore - 607006, Tamil Nadu','https://www.google.com/maps/search/?api=1&query=Immaculate+College+for+Women,+L.S.+Dupuis+Street,+Chinnakanganankuppam,+Cuddalore+-+607006,+Tamil+Nadu','https://immcolcud.edu.in','04142-222314, 210007, 210008, 8056779891','','https://collegeshine.com/wp-content/uploads/2026/07/Immaculate-College-for-Women-Cuddalore_42_11zon.webp','Immaculate College for Women | Cuddalore - CollegeShine','Immaculate College for Women is a private unaided (catholic minority institution) arts & science college in Chinnakanganankuppam, Cuddalore - 607006.',NULL, '{"id":"immaculate-college-for-women-cuddalore","seo":{"metaTitle":"Immaculate College for Women | Cuddalore - CollegeShine","metaDescription":"Immaculate College for Women is a private unaided (catholic minority institution) arts & science college in Chinnakanganankuppam, Cuddalore - 607006.","metaKeywords":["Immaculate College for Women","ICW","Immaculate College for Women admission 2026","Immaculate College for Women fees","Immaculate College for Women courses","Arts & Science colleges in Cuddalore","Chinnakanganankuppam","Cuddalore - 607006","Cuddalore","Arts & Science","Private Unaided (Catholic Minority Institution)","Arts and Science College for Women","UGC Recognised","AICTE Recognised","Annamalai University Affiliated","Catholic Minority Institution","Tamil","English","Mathematics","Physics","Chemistry"],"canonicalUrl":null,"robots":"index, follow","h1":"Immaculate College for Women","openGraph":{"title":"Immaculate College for Women | Cuddalore - CollegeShine","description":"Immaculate College for Women is a private unaided (catholic minority institution) arts & sci