 Wi-Fi"},{"icon":"ti-books","name":"Central Library"},{"icon":"ti-desktop","name":"Computer Lab"},{"icon":"ti-blackboard","name":"Smart Classrooms"},{"icon":"ti-home","name":"Hostel"},{"icon":"ti-bus","name":"Transport"},{"icon":"ti-world","name":"Language Lab"},{"icon":"ti-trophy","name":"Sports"},{"icon":"ti-microphone","name":"Seminar Hall"},{"icon":"ti-crown","name":"Placement Cell"},{"icon":"ti-light-bulb","name":"Innovation Cell"},{"icon":"ti-desktop","name":"Digital Learning Centre"}],"placementRate":78,"avgPackage":"2.8 LPA","highestPackage":"6.0 LPA","placementYear":null,"admissionProcess":[{"title":"Online Application","desc":"Register through the Tamil Nadu government common admissions website (tngasa.in)."},{"title":"Merit Screening","desc":"Madurai Kamarajar University guidelines determine academic merit ranking."},{"title":"Certificate Validation","desc":"Physical scrutiny of qualifying mark statements and community certificates."},{"title":"Counseling Sessions","desc":"Single-window transparent seat allocation based on category quotas."},{"title":"Final Admission","desc":"Fee payment and institutional enrollment registration."}],"scholarships":["Tamil Nadu Post Matric Scholarship for SC/ST/SCC","BC/MBC/DNC State Government Scholarship","First Graduate Tuition Waiver Concession","Central Sector Scholarship for College Students","National Merit Scholarship Award","Tamil Nadu Educational Support Grant for Women","Minority Welfare Scholarship Scheme","Alumni Association Endowments and Merit Awards"],"events":["Meenakshi Fest Annual Cultural Extravaganza","Inter-Collegiate Academic Symposia","National Science Day Exhibitions","Annual Sports Meet","NCC and NSS Special Day Parades","Entrepreneurship Development Cell Conclave"],"distanceInfo":{"airport":"Madurai International Airport - 12 km","railway":"Madurai Junction Railway Station - 2 km","bustand":"Periyar Bus Stand - 1 km","metro":"Not Applicable","hospital":"Government Rajaji Hospital Madurai - 1.5 km