","name":"Hostel"},{"icon":"ti-bus","name":"Transport"},{"icon":"ti-world","name":"Language Lab"},{"icon":"ti-trophy","name":"Sports"},{"icon":"ti-microphone","name":"Seminar Hall"},{"icon":"ti-crown","name":"Placement Cell"},{"icon":"ti-light-bulb","name":"Innovation Cell"},{"icon":"ti-desktop","name":"Digital Learning Centre"}],"placementRate":78,"avgPackage":"2.8 LPA","highestPackage":"5.5 LPA","placementYear":null,"admissionProcess":[{"title":"Application Submission","desc":"Eligible candidates must apply online through the official college admission portal."},{"title":"Merit List Preparation","desc":"Selections are strictly based on marks secured in the qualifying higher secondary or undergraduate examinations."},{"title":"Certificate Verification","desc":"Shortlisted candidates are called for physical verification of original academic and community certificates."},{"title":"Counseling & Fee Payment","desc":"Candidates participate in counseling sessions to select their preferred course and complete admission fee payment."},{"title":"Enrollment","desc":"Final allotment and class commencement updates are officially notified to enrolled students."}],"scholarships":["Government Post Matric Scholarship","BC/MBC State Scholarship","SC/ST Educational Concession","First Graduate Tuition Fee Waiver","Minority Welfare Scholarship","Alumni Association Merit Scholarship","Management Sponsored Free Education","Endowment Scholarships for Toppers"],"events":["College Annual Day","Inter-Collegiate Cultural Fest","National Science Day Symposium","Sports Meet","Alumni Meet","Department Association Valediction"],"distanceInfo":{"airport":"Madurai Airport - 100 km","railway":"Madurai Junction - 95 km","bustand":"Periyakulam Bus Stand - 2 km","metro":"N/A","hospital":"Government Hospital Periyakulam - 3 km"},"hostelFeatures":["Spacious and well-ventilated rooms","24/7 Security and CCTV surveillance","Nutritious and hygienic mess facility","Wi-Fi connectivity inside hostel premises"