bsite","url":null},"twitterCard":{"card":"summary_large_image","title":"Government Arts and Science College, Harur - CollegeShine","description":"Government Arts and Science College, Harur is a government arts & science college in Harur established in 2011. Developing an educationally backward taluk.","image":"https://collegeshine.com/wp-content/uploads/2026/07/Government-Arts-and-Science-College-Harur-collegshine_3_11zon.webp"},"structuredData":{"schemaType":"CollegeOrUniversity","jsonLd":null,"includeFaqSchema":true,"includeBreadcrumbSchema":true}},"name":"Government Arts and Science College, Harur","shortName":"GASC Harur","tagline":"Developing an educationally backward taluk since 2011","category":"arts-science","type":"Degree College","ownership":"Government","established":"2011","location":"Harur","district":"Dharmapuri","address":"Government Arts and Science College, Near GH, Opposite ASTC Depot, Morappur Main Road, Harur, Dharmapuri District - 636903, Tamil Nadu, India","mapLink":"https://www.google.com/maps/search/?api=1&query=Government+Arts+and+Science+College+Harur","mapQuery":"Government Arts and Science College, Harur, Dharmapuri, Tamil Nadu 636903","website":"https://www.periyaruniversity.ac.in/harur.php","phone":"04346-222212","email":null,"image":"https://collegeshine.com/wp-content/uploads/2026/07/Government-Arts-and-Science-College-Harur-collegshine_3_11zon.webp","videoUrl":null,"affiliation":"Periyar University, Salem","accreditation":[],"about":"Government Arts and Science College, Harur was started by the Government of Tamil Nadu via G.O. (Perm) No. 35 dated 18 July 2011, and affiliated to Periyar University on 22 July 2011 as a constituent college, in recognition of Harur taluk being among the most educationally backward areas of Dharmapuri district. The college is located next to the Harur Government Hospital on Morappur Main Road, on a 3-acre campus that it operates from its own premises. It began academic operations in 2011 with four undergraduate courses: B.A. English, B.Com, B.Sc. Botany and B.Sc. Computer Science.\\n\\nIn 2016 the college added a B.Sc. Mathematics course, and in 2017 it introduced a further UG course (B.A. Tamil) along with its first postgraduate course, M.A. English. At present around 953 students are enrolled across these six courses. The college''s stated vision is to equip rural students with the knowledge and skills needed to meet growing social, economic and technological challenges, making it an important access point for higher education in one of Dharmapuri district''s more remote taluks.","highlights":["Started 18 July 2011 to serve an educationally backward taluk","Affiliated to Periyar University, Salem (22 July 2011)","Began with 4 UG courses; added Mathematics (2016) and Tamil + first PG course (2017)","Around 953 students enrolled on a 3-acre campus"],"departments":[{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"}],"facilities":[],"placementRate":0,"avgPackage":null,"highestPackage":null,"placementYear":null,"admissionProcess":["10+2 pass required for UG admission","Bachelor''s degree required for PG admission","Merit-based selection per Periyar University norms"],"scholarships":[],"events":[],"distanceInfo":{},"hostelFeatures":[],"technicalClubs":[],"culturalClubs":[],"communityService":[]}'),
