('sri-sarada-college-for-women-salem','sri-sarada-college-for-women-salem','Sri Sarada College for Women (Autonomous), Salem','SSCW Salem','arts-science','Arts and Science College for Women','Government-Aided, Autonomous','1961','Fairlands, Salem','Salem','Sarada College Road, KMS Garden, Fairlands, Salem, Tamil Nadu 636016','https://www.google.com/maps/search/?api=1&query=Sri+Sarada+College+for+Women+Salem','https://www.srisaradacollege.ac.in/','0427-4550291','guham8@yahoo.co.in','https://collegeshine.com/wp-content/uploads/2026/07/Sri-Sarada-College-for-Women-Autonomus-Ariyakulam-Tirunelveli_69_11zon.webp','Sri Sarada College for Women (Autonomous), Salem - CollegeShine','Sri Sarada College for Women (Autonomous), Salem is a government-aided, autonomous arts & science college in Fairlands, Salem established in 1961.',NULL, '{"id":"sri-sarada-college-for-women-salem","seo":{"metaTitle":"Sri Sarada College for Women (Autonomous), Salem - CollegeShine","metaDescription":"Sri Sarada College for Women (Autonomous), Salem is a government-aided, autonomous arts & science college in Fairlands, Salem established in 1961.","metaKeywords":["Sri Sarada College for Women (Autonomous)","Salem","SSCW Salem","Sri Sarada College for Women (Autonomous)","Salem admission 2026","Sri Sarada College for Women (Autonomous)","Salem fees","Sri Sarada College for Women (Autonomous)","Salem courses","Arts & Science colleges in Salem","Fairlands","Salem","Salem","Arts & Science","Government-Aided","Autonomous","Arts and Science College for Women","NAAC B++ Grade","UGC 2(f) and 12(B)"],"canonicalUrl":null,"robots":"index, follow","h1":"Sri Sarada College for Women (Autonomous), Salem","openGraph":{"title":"Sri Sarada College for Women (Autonomous), Salem - CollegeShine","description":"Sri Sarada College for Women (Autonomous), Salem is a government-aided, autonomous arts & science college in Fairlands, Salem established in 1961.","image":"https://collegeshine.com/wp-content/uploads/2026/07/Sri-Sarada-College-for-Women-Autonomus-Ariyakulam-Tirunelveli_69_11zon.webp","type":"website","url":null},"twitterCard":{"card":"summary_large_image","title":"Sri Sarada College for Women (Autonomous), Salem - CollegeShine","description":"Sri Sarada College for Women (Autonomous), Salem is a government-aided, autonomous arts & science college in Fairlands, Salem established in 1961.","image":"https://collegeshine.com/wp-content/uploads/2026/07/Sri-Sarada-College-for-Women-Autonomus-Ariyakulam-Tirunelveli_69_11zon.webp"},"structuredData":{"schemaType":"CollegeOrUniversity","jsonLd":null,"includeFaqSchema":true,"includeBreadcrumbSchema":true}},"name":"Sri Sarada College for Women (Autonomous), Salem","shortName":"SSCW Salem","tagline":null,"category":"arts-science","type":"Arts and Science College for Women","ownership":"Government-Aided, Autonomous","established":"1961","location":"Fairlands, Salem","district":"Salem","address":"Sarada College Road, KMS Garden, Fairlands, Salem, Tamil Nadu 636016","mapLink":"https://www.google.com/maps/search/?api=1&query=Sri+Sarada+College+for+Women+Salem","mapQuery":"Sri Sarada College for Women, Fairlands, Salem","website":"https://www.srisaradacollege.ac.in/","phone":"0427-4550291","email":"guham8@yahoo.co.in","image":"https://collegeshine.com/wp-content/uploads/2026/07/Sri-Sarada-College-for-Women-Autonomus-Ariyakulam-Tirunelveli_69_11zon.webp","videoUrl":"","affiliation":"Periyar University, Salem","accreditation":["NAAC B++ Grade","UGC 2(f) and 12(B)"],"about":"Sri Sarada College for Women (Autonomous) in Salem was established in 1961 by Mrs. Seethalakshmi Ramaswamy under the guidance of Swami Chidbhavananda of Sri Ramakrishna Tapovanam, Tirupparaithurai, and was initially affiliated to the University of Madras. Since 1998 the college has been affiliated to Periyar University, Salem, and it received autonomous status from the UGC in 1988-89. It is a government-aided women''s institution recognized under UGC Sections 2(f) and 12(B), and has been accredited by NAAC across multiple cycles, most recently with a B++ grade.\\n\\nThe college offers twelve undergraduate programmes, seven postgraduate programmes, nine M.Phil programmes, and nine Ph.D programmes, along with self-financing PG programmes including M.Sc. Data Science and M.Com. It provides on-campus hostel accommodation with a vegetarian mess, CCTV surveillance, and female wardens for outstation students. Recruiters that have historically placed students from the college include LIC Salem, TCS, Infosys, HCL, and CTS, among others, reflecting a placement focus geared toward IT-enabled services and BPO roles alongside traditional arts, science, and commerce careers.","highlights":["Autonomous status since 1988-89","NAAC B++ accredited","Twelve UG and seven PG programmes","Dedicated women''s hostel with 24x7 CCTV"],"departments":[{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"},{"name":null,"level":"UG"}],"facilities":["Library","Science Laboratories","Women''s Hostel","Vegetarian Mess","CCTV Surveillance"],"placementRate":0,"avgPackage":null,"highestPackage":null,"placementYear":null,"admissionProcess":["Merit-based selection using Class 12 qualifying marks","Online application fee of Rs. 48, registration fee Rs. 2 per college","Both online and offline admission modes available"],"scholarships":["Merit-based scholarships for academic excellence","Scholarships for extracurricular achievement"],"events":[],"distanceInfo":{},"hostelFeatures":["24x7 CCTV surveillance","Female wardens","Vegetarian mess","Morning prayer sessions","Library access after college hours"],"technicalClubs":[],"culturalClubs":[],"communityService":[]}'),
