ementYear":null,"admissionProcess":[{"title":"Check Eligibility","desc":"Review programme-wise eligibility criteria as prescribed by Bharathiar University for the desired UG or PG course."},{"title":"Obtain Application Form","desc":"Download the application form or prospectus from the official college website (ehcfw.ac.in) or collect it in person from the admission office."},{"title":"Submit Application","desc":"Complete and submit the filled application along with required academic certificates within the announced admission window."},{"title":"Merit-Based Selection","desc":"Admission is based on merit as per the college''s stated admission procedure; shortlisted candidates may be called for document verification."},{"title":"Fee Payment & Enrollment","desc":"Confirm admission by paying the prescribed fees and completing enrollment formalities with the college office."}],"scholarships":["Government Scholarships","SC/ST Scholarship Support","Merit Scholarship through Fee Concession","Scholarship Support for Economically Weak Students","Government Financial Assistance Schemes","Post-Matric Scholarship Support","Student Welfare Scholarship Assistance"],"events":["International Yoga Day","Annual College Day","Freshers Day","Teachers Day","Christmas Celebration","Pongal Celebration","Women''s Day","Hostel Day","Farewell Party","Independence Day","Republic Day","Sports Day","NSS Extension Activities","Red Ribbon Club Activities","Youth Red Cross Activities"],"distanceInfo":{"airport":"Approximately 25 km","railway":"Approximately 25 km","bustand":"Approximately 15 km","metro":"Not Available","hospital":"Approximately 2 km"},"hostelFeatures":["Women''s Hostel Facility","Female Wardens and Supervisors","24x7 Hostel Supervision","Visitor Monitoring System","Student Safety and Security","Hostel Representative System","Hostel Day Activities","Mentoring and Counselling Support"],"technicalClubs":["Computer Science Club","Information Technology Club","Computer Technology Club",