('gobi-arts-and-science-college-gobichettipalayam','gobi-arts-and-science-college-gobichettipalayam','Gobi Arts & Science College','GASC','arts-science','Co-educational, Autonomous','Government Aided Autonomous','1968','Karattadipalayam, Gobichettipalayam','Erode','Karattadipalayam Post, Gobichettipalayam Taluk, Erode District - 638453, Tamil Nadu','https://www.google.com/maps/search/?api=1&query=Gobi+Arts+and+Science+College+Karattadipalayam+Gobichettipalayam','https://gascgobi.ac.in/','04285-240147 / 04285-240741','gobiartscollege@gascgobi.ac.in','https://collegeshine.com/wp-content/uploads/2026/07/Gobi-Arts-Science-College-collegshine_9_11zon-150x150.webp','Gobi Arts & Science College | Erode - CollegeShine','Gobi Arts & Science College is a government aided autonomous arts & science college in Karattadipalayam, Gobichettipalayam established in 1968. Value-based.',NULL, '{"id":"gobi-arts-and-science-college-gobichettipalayam","seo":{"metaTitle":"Gobi Arts & Science College | Erode - CollegeShine","metaDescription":"Gobi Arts & Science College is a government aided autonomous arts & science college in Karattadipalayam, Gobichettipalayam established in 1968. Value-based.","metaKeywords":["Gobi Arts & Science College","GASC","Gobi Arts & Science College admission 2026","Gobi Arts & Science College fees","Gobi Arts & Science College courses","Arts & Science colleges in Erode","Karattadipalayam","Gobichettipalayam","Erode","Arts & Science","Government Aided Autonomous","Co-educational","Autonomous","NAAC A Grade","UGC Recognized","Autonomous Status","Affiliated to Bharathiar University","Tamil","English","Economics","Commerce","Management"],"canonicalUrl":null,"robots":"index, follow","h1":"Gobi Arts & Science College","openGraph":{"title":"Gobi Arts & Science College | Erode - CollegeShine","description":"Gobi Arts & Science College is a government aided autonomous arts & science college in Karattadipalayam, Gobichettipalayam established in 1968. Value-based.","image