al NGM College admission process."},{"title":"Merit Selection","desc":"UG admissions are generally processed according to qualifying examination marks and applicable admission regulations."},{"title":"Entrance Process","desc":"Where applicable, postgraduate or research admissions follow the relevant institutional and university requirements."},{"title":"Document Verification","desc":"Submit academic certificates, transfer certificate, community certificate and other required documents for verification."},{"title":"Fee Payment","desc":"Complete the prescribed fee payment and admission formalities after selection."},{"title":"Enrollment","desc":"Report to the college and complete final enrollment and academic registration."}],"scholarships":["Government Scholarships","Post Matric Scholarships","SC/ST Scholarships","BC/MBC Scholarships","Minority Scholarships","First Graduate Scholarship","Merit Scholarships"],"events":["Annual College Day","Alumni Association Events","Departmental Seminars","Academic Workshops","Research Conferences","NEP 2020 Seminars","NPTEL Activities","National Science Day","Career Development Programmes","Industry Interaction Programmes","Sports Events","Cultural Programmes"],"distanceInfo":{"airport":"55 km","railway":"1 km","bustand":"2 km","metro":"N/A","hospital":"2 km"},"hostelFeatures":["Separate Hostel Facilities","Student Accommodation","Study Facilities","Mess Facilities","Security","Common Facilities","Student Support"],"technicalClubs":["Cyber Security Club","Quiz Club","NEXAURA","PLEXUS","Computer Applications Association","Technical Meet","IT Association"],"culturalClubs":["Fine Arts","Literary Activities","Book Talk Forum","Thespian Club","Music Activities","Drama Activities","Quiz Club","Yoga Centre"],"communityService":["NSS","NCC","Rotaract Club","Youth Red Cross","Community Outreach","Environmental Activities","Digital India Awareness","Blood Donation Activities","Village Outreach","Tree Plantation","Social Awareness Programmes"