icants complete verification of academic and supporting documents at the college."},{"title":"Fee Payment","desc":"Candidates confirm admission by completing the prescribed fee and enrollment formalities."}],"scholarships":["Merit Scholarship","Single Parent Scholarship","Sports Scholarship","Government Scholarship","Trust Sponsored Scholarship","First Generation Scholarship"],"events":["Annual College Day","Skill Development Programmes","Career Development Programmes","Industry Interaction","Department Seminars","Research Activities","Student Cultural Programmes","Sports Activities","Community Outreach","School Engagement Programmes"],"distanceInfo":{"airport":"25 km","railway":"12 km","bustand":"10 km","metro":"N/A","hospital":"5 km"},"hostelFeatures":["Student Hostel","Security","Study Facilities","Dining","Recreation","Student Support"],"technicalClubs":["Computer Science Club","Technology Club","Skill Development Cell","Career Development Cell","Research Cell"],"culturalClubs":["Tamil Literary Club","Fine Arts Club","Music Club","Dance Club","Drama Club","Yoga Club"],"communityService":["School Outreach","Community Engagement","NSS Activities","Women Welfare Activities","Environmental Activities","Student Awareness Programmes"]}'),
