tion Cell"},{"icon":"ti-desktop","name":"Digital Learning Centre"}],"placementRate":82,"avgPackage":"2.2 LPA","highestPackage":"3.6 LPA","placementYear":null,"admissionProcess":[{"title":"Eligibility Check","desc":"Candidates must have passed the 10th standard (SSLC) examination or equivalent from a recognized board."},{"title":"Application Submission","desc":"Obtain and submit the filled application form through the official website or directly at the college admission office."},{"title":"Merit Preparation","desc":"Selections are strictly based on marks secured in the qualifying 10th standard examination as per DOTE norms."},{"title":"Counseling & Verification","desc":"Attend the counseling session for seat allotment and complete document verification."},{"title":"Fee Payment & Enrollment","desc":"Confirm admission by paying the prescribed tuition fees and completing enrollment formalities."}],"scholarships":["First Graduate Tuition Fee Concession","Post Matric Scholarship for SC/ST Students","BC/MBC State Government Scholarship","Minority Welfare Scholarship","Chief Minister''s Uzhavar Pathukappu Thittam Scholarship","Pudhumai Penn Scheme for Girl Students","Management Merit Scholarship","Ex-Servicemen Ward Scholarship"],"events":["Annual Technical Symposium","National Science Day Celebration","Annual Sports Meet","Graduation Day Ceremony","Cultural Fest - Sutharshan","Inter-Polytechnic Workshop"],"distanceInfo":{"airport":"Madurai Airport - 75 KM","railway":"Sivaganga Railway Station - 23.4 KM","bustand":"Sivaganga Bus Stand - 22.7 KM","metro":"Not Available","hospital":"Government Hospital Kalayarkovil - 3 KM"},"hostelFeatures":["Spacious and well-ventilated rooms","24/7 Water supply and electricity backup","Secure environment with security guards","Nutritious and hygienic mess facility","Reading room and recreation hall","Medical assistance on call","Wi-Fi connectivity","Clean and sanitized washrooms"],"technicalClubs":["Mechanical Engineering Association","Ele