('government-medical-college-and-hospital-chidambaram','government-medical-college-and-hospital-chidambaram','Government Medical College & Hospital, Chidambaram (Dept. of PMR — Occupational Therapy)','GMC Chidambaram (Occupational Therapy)','occupational-therapy','Government Medical College','Government (Government of Tamil Nadu, under DME)','1994','Chidambaram','Cuddalore','Annamalai Nagar, Chidambaram, Cuddalore District, Tamil Nadu 608002','https://maps.google.com/?q=Government+Medical+College+and+Hospital+Chidambaram','https://www.governmentmedicalcollegeandhospitalcuddaloredistrict.com/','','mailto:deanrmmc@gmail.com','https://collegeshine.com/wp-content/uploads/2026/08/Government_Cuddalore_Medical_College_collegeshine.webp','Government Medical College & Hospital - CollegeShine','Government Medical College & Hospital, Chidambaram (Dept. of PMR — Occupational Therapy) is a government (government of tamil nadu, under dme) occupational.',NULL, '{"id":"government-medical-college-and-hospital-chidambaram","seo":{"metaTitle":"Government Medical College & Hospital - CollegeShine","metaDescription":"Government Medical College & Hospital, Chidambaram (Dept. of PMR — Occupational Therapy) is a government (government of tamil nadu, under dme) occupational.","metaKeywords":["Government Medical College & Hospital","Chidambaram (Dept. of PMR — Occupational Therapy)","GMC Chidambaram (Occupational Therapy)","Government Medical College & Hospital","Chidambaram (Dept. of PMR — Occupational Therapy) admission 2026","Government Medical College & Hospital","Chidambaram (Dept. of PMR — Occupational Therapy) fees","Government Medical College & Hospital","Chidambaram (Dept. of PMR — Occupational Therapy) courses","Occupational Therapy colleges in Cuddalore","Chidambaram","Cuddalore","Occupational Therapy","Government (Government of Tamil Nadu","under DME)","Government Medical College","Government Institution under DME","Tamil Nadu","Affiliated to The Tamil Nadu Dr. M.G.R. Medical University","One of Three Premier PMR Centres in Tamil Nadu (with GRIM Chennai & CMC Vellore)","BOT (Bachelor of Occupational Therapy)"],"canonicalUrl":null,"robots":"index, follow","h1":"Government Medical College & Hospital, Chidambaram (Dept. of PMR — Occupational Therapy)","openGraph":{"title":"Government Medical College & Hospital - CollegeShine","description":"Government Medical College & Hospital, Chidambaram (Dept. of PMR — Occupational Therapy) is a government (government of tamil nadu, under dme) occupational.","image":"https://collegeshine.com/wp-content/uploads/2026/08/Government_Cuddalore_Medical_College_collegeshine.webp","type":"website","url":null},"twitterCard":{"card":"summary_large_image","title":"Government Medical College & Hospital - CollegeShine","description":"Government Medical College & Hospital, Chidambaram (Dept. of PMR — Occupational Therapy) is a government (government of tamil nadu, under dme) occupational.","image":"https://collegeshine.com/wp-content/uploads/2026/08/Government_Cuddalore_Medical_College_collegeshine.webp"},"structuredData":{"schemaType":"CollegeOrUniversity","jsonLd":null,"includeFaqSchema":true,"includeBreadcrumbSchema":true}},"name":"Government Medical College & Hospital, Chidambaram (Dept. of PMR — Occupational Therapy)","shortName":"GMC Chidambaram (Occupational Therapy)","tagline":"Rehabilitation for All","category":"occupational-therapy","type":"Government Medical College","ownership":"Government (Government of Tamil Nadu, under DME)","established":1994,"location":"Chidambaram","district":"Cuddalore","address":"Annamalai Nagar, Chidambaram, Cuddalore District, Tamil Nadu 608002","mapLink":"https://maps.google.com/?q=Government+Medical+College+and+Hospital+Chidambaram","mapQuery":"Government+Medical+College+and+Hospital+Chidambaram","website":"https://www.governmentmedicalcollegeandhospitalcuddaloredistrict.com/","phone":"","email":"mailto:deanrmmc@gmail.com","image":"https://collegeshine.com/wp-content/uploads/2026/08/Government_Cuddalore_Medical_College_collegeshine.webp","videoUrl":"https://www.youtube.com/embed/WTeNnadsGUA?si=gDvhVvjq4-wyo_GG&amp;start=7","affiliation":"Affiliated to Tamil Nadu Dr. M.G.R. Medical University; functioning under the Directorate of Medical Education (DME), Government of Tamil Nadu since 2021 (formerly Rajah Muthiah Medical College, Annamalai University)","accreditation":["Government Institution under DME, Tamil Nadu","Affiliated to The Tamil Nadu Dr. M.G.R. Medical University","One of Three Premier PMR Centres in Tamil Nadu (with GRIM Chennai & CMC Vellore)"],"about":"The Bachelor of Occupational Therapy (BOT) programme at Government Medical College and Hospital, Chidambaram (erstwhile Rajah Muthiah Medical College) is run within the Department of Physical Medicine & Rehabilitation (PMR), one of only three premier PMR centres in Tamil Nadu alongside the Government Institute of Rehabilitation Medicine, Chennai, and CMC Vellore. The BOT course began in 1994 and offers 20 seats, with a 4-year academic programme followed by a 6-month internship.\\n\\nThe PMR division grew from a two-member unit in a 500 sq ft space to a full-fledged division with separate sections for Physiotherapy, Occupational Therapy, an Artificial Limb Centre, Play Therapy, and a Community Rehabilitation Programme, spread over 22,000 sq ft. The college itself was established in 1985, named after philanthropist Rajah Muthiah Chettiar, and was taken over by the Government of Tamil Nadu in February 2021 under G.O. 45, functioning under the Directorate of Medical Education (DME) since then. The attached hospital has 1,250 beds and treats around 2,800–3,000 outpatients daily.","highlights":["BOT Course Running Since 1994 — 20 Seats","One of Three Premier PMR Centres in Tamil Nadu","Attached to 1,250-Bed Government Hospital","Separate Occupational Therapy, Physiotherapy, Artificial Limb Centre, Play Therapy & Community Rehab Sections","22,000 Sq Ft Dedicated PMR Division Facility","Government Institution — Affordable Fee Structure","Interdisciplinary Curriculum with English, Psychology, Sociology, Yoga & More","Alumni Placed Across India and Abroad"],"departments":[{"name":"BOT (Bachelor of Occupational Therapy)","level":"UG"}],"facilities":[{"icon":"ti-wifi","name":"Campus Network with Internet Section"},{"icon":"ti-books","name":"Central Medical Library (22,429 Books)"},{"icon":"ti-flask","name":"Occupational Therapy & Rehabilitation Labs"},{"icon":"ti-home","name":"Separate Hostels (Boys & Girls)"},{"icon":"ti-bus","name":"Transport Block"},{"icon":"ti-heartbeat","name":"1,250-Bed Multi-Speciality Hospital"},{"icon":"ti-crown","name":"Artificial Limb Centre"},{"icon":"ti-heart","name":"Play Therapy Section"},{"icon":"ti-trophy","name":"Sports Activities"},{"icon":"ti-microphone","name":"Air-Conditioned Lecture Halls"},{"icon":"ti-cpu","name":"Community Rehabilitation Programme"},{"icon":"ti-medall","name":"Doctor''s Cafeteria"}],"placementRate":75,"avgPackage":"₹2.8 LPA","highestPackage":"₹5.5 LPA","placementYear":null,"admissionProcess":[{"title":"Meet Eligibility Criteria","desc":"Candidates must have completed 10+2 with Physics, Chemistry, Biology as per Tamil Nadu allied health sciences admission norms."},{"title":"Apply via Tamil Nadu Paramedical / Allied Health Counselling","desc":"Register through the applicable state government counselling process for allied health science seats."},{"title":"Choice Filling","desc":"Select Government Medical College and Hospital, Chidambaram BOT as a preference during counselling."},{"title":"Document Verification & Seat Allotment","desc":"Complete document verification; seats are allotted based on merit and category reservation."},{"title":"Reporting & Enrollment","desc":"Report to the college with original documents to confirm admission into the BOT programme."}],"scholarships":["Tamil Nadu Government Scholarship Schemes (as applicable to Allied Health Sciences students)"],"events":["Academy of Med