l-therapy/","phone":"+91 93612 04122, +91 98422 02288, +91 84899 68555","email":"mailto:mail@revathiinstitutions.com","image":"https://collegeshine.com/wp-content/uploads/2026/08/Revathi-Institute-of-Occupational-Therapy-and-Medical-Research-collegeshine-1.webp","videoUrl":"https://www.youtube.com/embed/QFqJzldA4Zs?si=yAB9gfPytCyF5rRe","affiliation":"Affiliated to The Tamil Nadu Dr. M.G.R. Medical University; part of the Revathi Institutions Group, trained at Revathi Medical Center (RMC) — parent super speciality hospital","accreditation":["Affiliated to The Tamil Nadu Dr. M.G.R. Medical University","Trained at Revathi Medical Center (RMC) — 300-Bed Super Speciality Parent Hospital","Part of Revathi Institutions Group — 14+ Years in Healthcare Education"],"about":"The Institute of Occupational Therapy at Revathi Institutions offers the Bachelor of Occupational Therapy (BOT), a health and social care programme focused on enabling people of all ages to regain independence and participate in the activities of everyday life. The programme is a 4-year academic course followed by a 6-month internship, with eligibility requiring a pass in HSC or equivalent.\\n\\nRevathi Institutions is located on a 13-acre eco-friendly campus with a built-up area of over 300,000 sq. ft. on the Coimbatore Bypass between Tirupur and Coimbatore, offering more than 15 undergraduate and postgraduate healthcare programmes across Nursing, Physiotherapy, Occupational Therapy, and Paramedical Sciences. Students are trained at Revathi Medical Center (RMC), the institution''s own 300-bed super speciality parent hospital, equipped with cutting-edge medical equipment and staffed by experienced consultants across medical and surgical fields. The BOT curriculum covers core competencies in Neurorehabilitation, Child Habilitation, Psychosocial Rehabilitation, Hand Rehabilitation, Musculoskeletal Rehabilitation, Splinting & Assistive Technology, Geriatric Care, Neonatal Intensive Care, and Community-Based Services.","highlights":["BOT — 4 Years + 6-Month Internship","13-Acre Eco-Friendly Campus, 300,000+ Sq Ft Built-Up Area","Trained at Own 300-Bed Super Speciality Hospital (RMC)","Affiliated to The Tamil Nadu Dr. M.G.R. Medical University","14+ Years of Healthcare Education Experience","15+ UG & PG Healthcare Programmes on Campus","Modern Digital Classrooms & High-Tech Labs","Strong Focus on Neurorehabilitation, Hand Therapy & Community-Based Services"],"departments":[{"name":"BOT (Bachelor of Occupational Therapy)","level":"UG"}],"facilities":[{"icon":"ti-wifi","name":"Digital Classrooms"},{"icon":"ti-books","name":"Expansive Library"},{"icon":"ti-flask","name":"High-Tech Labs"},{"icon":"ti-home","name":"Hostel Facility"},{"icon":"ti-bus","name":"Transport Facility"},{"icon":"ti-heartbeat","name":"Revathi Medical Center — 300-Bed Super Speciality Hospital"},{"icon":"ti-crown","name":"Placement Support"},{"icon":"ti-heart","name":"Clinical Training Labs"},{"icon":"ti-trophy","name":"Sports & Recreation"},{"icon":"ti-microphone","name":"Seminar Halls"},{"icon":"ti-cpu","name":"Smart Classrooms"},{"icon":"ti-medall","name":"Research Support"}],"placementRate":82,"avgPackage":"₹3.2 LPA","highestPackage":"₹6.5 LPA","placementYear":null,"admissionProcess":[{"title":"Meet Eligibility Criteria","desc":"Candidates must have a pass in HSC (10+2) or equivalent examination."},{"title":"Apply Online","desc":"Complete the online application form via the official Revathi Institutions application portal — takes about 10 minutes."},{"title":"Admissions Team Connect","desc":"An admissions representative contacts the candidate and guides them through the remaining process."},{"title":"Document Verification & Fee Payment","desc":"Submit required documents and complete fee payment to confirm the seat."},{"title":"Orientation & Enrollment","desc":"Report to the campus for orientation and final enrollment into the BOT programme."}],"scholarships":["Merit-Based Scholarships (Institution-Wide, as per Revathi Institutions policy)"],"events":["Freshers'' Day","Annual College Day","World Occupational Therapy Day","Sports Meet","Cultural Fest"],"distanceInfo":{"airport":"45 km (Coimbatore)","railway":"12 km (Tirupur)","bustand":"2 km (Ganani Bus Stop)","metro":"N/A","hospital":"On Campus (Revathi Medical Center)"},"hostelFeatures":["Separate Boys & Girls Hostels","Wi-Fi Facility","Mess Facility","24x7 Security","Recreation Areas"],"technicalClubs":["Occupational Therapy Research Club","Clinical Skill Development Club","Assistive Technology & Splinting Club"],"culturalClubs":["Dance Club","Music Club","Fine Arts Club"],"communityService":["Community-Based Rehabilitation Outreach","Free Health Camps","Blood Donation Camps"]}'),
