('schieffelin-institute-health-research-leprosy-centre-vellore','schieffelin-institute-health-research-leprosy-centre-vellore','Schieffelin Institute of Health – Research & Leprosy Centre','SIHRLC Karigiri','allied-health-science','Private Research & Training Institute (Charitable Trust)','Private (Christian Charitable Trust — Affiliated to Christian Medical Association of India)','1955','Karigiri','Vellore','Schieffelin Institute of Health – Research & Leprosy Centre, Karigiri – 632106, (via Katpadi), Vellore District, Tamil Nadu, India','https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3887.6822430871875!2d79.17945331430454!3d12.99216421794322!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3bad47cb3f574211%3A0xb12e02cab221695b!2sSCHIEFFELIN%20INSTITUTE%20OF%20HEALTH%20RESEARCH%20AND%20LEPROSY%20CENTER%20(SIHR%26LC)!5e0!3m2!1sen!2sin!4v1638527076738!5m2!1sen!2sin','https://leprosyhealth.org/','0416-2999-223, 0416-2999-224, 0416-2999-227, 0416-2999-228, 0416-2999-229','directorate@karigiri.org, publicrelations@karigiri.org','https://leprosyhealth.org/wp-content/uploads/2026/07/SIHRLC_LOGO.png','Schieffelin Institute of Health – Research & - CollegeShine','Schieffelin Institute of Health – Research & Leprosy Centre is a private (christian charitable trust — affiliated to christian medical association of india).',NULL, '{"id":"schieffelin-institute-health-research-leprosy-centre-vellore","seo":{"metaTitle":"Schieffelin Institute of Health – Research & - CollegeShine","metaDescription":"Schieffelin Institute of Health – Research & Leprosy Centre is a private (christian charitable trust — affiliated to christian medical association of india).","metaKeywords":["Schieffelin Institute of Health – Research & Leprosy Centre","SIHRLC Karigiri","Schieffelin Institute of Health – Research & Leprosy Centre admission 2026","Schieffelin Institute of Health – Research & Leprosy Centre fees","Schieffelin Institute of Health – Research & Leprosy Centre courses","Allied Health Science colleges in Vellore","Karigiri","Vellore","Allied Health Science","Private (Christian Charitable Trust — Affiliated to Christian Medical Association of India)","Private Research & Training Institute (Charitable Trust)","Affiliated to The Tamil Nadu Dr. M.G.R. Medical University","Chennai (Official)","Accredited by Christian Medical Association of India (CMAI) (Official)","Accredited by Rehabilitation Council of India (RCI) for B.Sc. Prosthetics & Orthotics (Official)","WHO Collaborating Centre for Leprosy Research & Training (Official)","B.Sc. Medical Laboratory Technology","B.Sc. Medical Record Technology","B.Sc. Radiography & Imaging Technology","B.Sc. Optometry","B.Sc. Physician Assistant"],"canonicalUrl":null,"robots":"index, follow","h1":"Schieffelin Institute of Health – Research & Leprosy Centre","openGraph":{"title":"Schieffelin Institute of Health – Research & - CollegeShine","description":"Schieffelin Institute of Health – Research & Leprosy Centre is a private (christian charitable trust — affiliated to christian medical association of india).","image":"https://leprosyhealth.org/wp-content/uploads/2026/07/SIHRLC_LOGO.png","type":"website","url":null},"twitterCard":{"card":"summary_large_image","title":"Schieffelin Institute of Health – Research & - CollegeShine","description":"Schieffelin Institute of Health – Research & Leprosy Centre is a private (christian charitable trust — affiliated to christian medical association of india).","image":"https://leprosyhealth.org/wp-content/uploads/2026/07/SIHRLC_LOGO.png"},"structuredData":{"schemaType":"CollegeOrUniversity","jsonLd":null,"includeFaqSchema":true,"includeBreadcrumbSchema":true}},"name":"Schieffelin Institute of Health – Research & Leprosy Centre","shortName":"SIHRLC Karigiri","tagline":"Transforming Lives Through Holistic Health and Healing","category":"allied-health-science","type":"Private Research & Training Institute (Charitable Trust)","ownership":"Private (Christian Charitable Trust — Affiliated to Christian Medical Association of India)","established":1955,"location":"Karigiri","district":"Vellore","address":"Schieffelin Institute of Health – Research & Leprosy Centre, Karigiri – 632106, (via Katpadi), Vellore District, Tamil Nadu, India","mapLink":"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3887.6822430871875!2d79.17945331430454!3d12.99216421794322!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3bad47cb3f574211%3A0xb12e02cab221695b!2sSCHIEFFELIN%20INSTITUTE%20OF%20HEALTH%20RESEARCH%20AND%20LEPROSY%20CENTER%20(SIHR%26LC)!5e0!3m2!1sen!2sin!4v1638527076738!5m2!1sen!2sin","mapQuery":"Schieffelin+Institute+of+Health+Research+Leprosy+Centre+Karigiri+Vellore","website":"https://leprosyhealth.org/","phone":"0416-2999-223, 0416-2999-224, 0416-2999-227, 0416-2999-228, 0416-2999-229","email":"directorate@karigiri.org, publicrelations@karigiri.org","image":"https://leprosyhealth.org/wp-content/uploads/2026/07/SIHRLC_LOGO.png","videoUrl":"https://www.youtube.com/embed/FFpHeigEpW8","affiliation":"Affiliated to The Tamil Nadu Dr. M.G.R. Medical University, Chennai; Accredited by Christian Medical Association of India (CMAI); Recognized by Rehabilitation Council of India (RCI); WHO Collaborating Centre","accreditation":["Affiliated to The Tamil Nadu Dr. M.G.R. Medical University, Chennai (Official)","Accredited by Christian Medical Association of India (CMAI) (Official)","Accredited by Rehabilitation Council of India (RCI) for B.Sc. Prosthetics & Orthotics (Official)","WHO Collaborating Centre for Leprosy Research & Training (Official)","Recognized as ''Centre of Excellence for Foot Care'' by World Diabetes Foundation (Official)","Recognized as ''Sentinel Surveillance Centre for Drug Resistance'' in Leprosy by WHO (Official)","NABH & NABL Certified (Official)"],"about":"Schieffelin Institute of Health – Research & Leprosy Centre (SIHRLC), established in 1955, is a leading private research, training, and clinical institution dedicated to leprosy management, rehabilitation, and comprehensive healthcare. Located in Karigiri village near Vellore, Tamil Nadu, the institute operates as a 150-bedded general hospital with specialization in leprosy care and integrates secondary-care services across 12+ departments including Dermatology, Ophthalmology, Surgery, ENT, General Medicine, Pediatrics, OB/GYN, Clinical Psychology, and Diagnostics.\\n\\nThe institute''s College of Health Sciences offers 11 undergraduate & diploma programs in Allied Health Sciences—B.Sc. Medical Laboratory Technology, Medical Record Technology, Radiography & Imaging Technology, Optometry, Physician Assistant, and Medical Sociology (all 3 years + 1-year internship); Diploma in General Nursing & Midwifery (3 years); Diploma programs in Medical Laboratory Technology, Radio Diagnosis Technology, and Medical Record Technology (2 years); and B.Sc. Prosthetics & Orthotics (4 years, RCI-approved). Total intake: 120+ seats across all programmes.\\n\\nSIHRLC is recognized globally as a WHO Collaborating Centre and has been a pioneer in leprosy research since 1968, when the Tamil Nadu Government entrusted it with the National Leprosy Eradication Program. The institute maintains active clinical training through rotations in its own hospital network and affiliated centers, publishes peer-reviewed research across multiple disciplines, and conducts community health programs including foot-care camps, vision screening, and occupational therapy rehabilitation.","highlights":["Established 1955 — Over 70 Years of Leprosy Research, Training & Healthcare Excellence","WHO Collaborating Centre for Leprosy Research & Training (Official Recognition)","11 UG & Diploma Programs in Allied Health Sciences — All TN Dr. MGR University Affiliated","150-Bedded General Hospital with Specialization in Leprosy Management & Secondary Care","Accredited by CMAI (Christian Medical Association of India) & RCI (Rehabilitation Council of India)","Clinical Training from Day One — Hospital Rotations, Ward Postings & Community Health Camps","Research-Focused Institution — Active Studies in Rehabilitation, Digital Innovations & Clinical Leprosy","Prosthetics & Orthotics Program (4-Year, RCI-Approved) — Unique Specialization in South India","Integrated Outreach Programs — Community Eye Screening, Foot Care, Occupational Therapy Rehabilitation","Faculty from International Leprosy Organizations & Academic Centers"],"departments":[{"name":"B.Sc. Medical Laboratory Technology","level":"UG"},{"name":"B.Sc. Medical Record Technology","level":"UG"},{"name":"B.Sc. Radiography & Imaging Technology","level":"UG"},{"name":"B.Sc. Optometry","level":"UG"},{"name":"B.Sc. Physician Assistant","level":"UG"},{"name":"B.Sc. Medical Sociology","level":"UG"},{"name":"B.Sc. Prosthetics & Orthotics","level":"UG"},{"name":"Diploma in General Nursing & Midwifery (GNM)","level":"Diploma"},{"name":"Diploma in Medical Laboratory Technology","level":"Diploma"},{"name":"Diploma in Radio Diagnosis Technology","level":"Diploma"},{"name":"Diploma in Medical Record Technology","level":"Diploma"}],"facilities":[{"icon":"ti-home","name":"150-Bedded General Hospital (Leprosy-Specialized, Integrated Secondary Care)"},{"icon":"ti-flask","name":"Advanced Laboratory Services (Molecular Biology, Animal House, Diagnostics)"},{"icon":"ti-microscope","name":"Smart Classrooms & Multimedia Teaching Labs"},{"icon":"ti-books","name":"Medical Library (5,000+ Books, Journals, Reference Materials)"},{"icon":"ti-medall","name":"Clinical Training Wards — Internal Medicine, Surgery, Pediatrics, OB/GYN, Dermatology, Ophthalmology"},{"icon":"ti-heart","name":"Physiotherapy & Occupational Therapy Centers"},{"icon":"ti-wifi","name":"Computer Lab & Internet Access (Wi-Fi Campus)"},{"icon":"ti-home","name":"Hostel Facilities (Boys, Girls, Co-Ed Hostels — 60+ Capacity)"},{"icon":"ti-restaurant","name":"Cafeteria & Dining Facilities"},{"icon":"ti-cup","name":"Sports Complex & Gymnasium"},{"icon":"ti-medall","name":"Auditorium & Seminar Halls"},{"icon":"ti-briefcase","name":"Career Guidance & Placement Cell"},{"icon":"ti-gift","name":"Community Health Camps (Eye Screening, Foot Care, Health Education)"}],"placementRate":78,"avgPackage":"₹2.0 LPA","highestPackage":"₹4.5 LPA","placementYear":null,"admissionProcess":[{"title":"Check Eligibility","desc":"12th pass with minimum 50% marks (varies by course & board); Stream preference based on specialization (Science for most courses). No NEET required for Allied Health programs (except where specified by University)."},{"title":"Online Application","desc":"Submit online application via official website https://leprosyhealth.org/ or through Tamil Nadu Dr. MGR Medical University portal. Complete personal, educational, and medical details."},{"title":"Document Submission","desc":"Upload scanned copies of 12th pass certificate, mark sheet, caste certificate (if applicable), medical fitness certificate, and other relevant documents."},{"title":"Merit-Based Counselling","desc":"Selected candidates are called for counselling based on merit ranking. Document verification conducted at the campus (Karigiri)."},{"title":"Final Enrollment","desc":"Successful candidates complete enrollment formalities, hostel allotment (if applicable), and admission to chosen program."}],"scholarships":["Merit-Based Fee Concessions (Limited, Case-by-Case)","Government Scholarships for SC/ST (As per State Policy)","Research Scholarships for Advanced Studies"],"events":["Community Eye-Care Screening Camps (Regular)","World Leprosy Day Celebrations & Awareness Programs (Annual, January 30)","Guest Lectures from International Leprosy Experts & Clinical Specialists","Industrial Visits to Hospital Networks & Research Centers","National Leprosy Eradication Program (NLEP) Training Workshops","International Conferences on Leprosy & Rehabilitation (Periodic)","Student Research Symposia & Scientific Presentations","Health Awareness & Community Outreach Programs","An