d 2021 by Dhanalakshmi Srinivasan Charitable and Educational Trust","Under Deemed to be University Status","25-Acre Green Campus Township","Over 2 Million Sq. Ft. of Constructed Space","Central Library Learning Centre — One of the Region''s Largest Medical Libraries","Air-Conditioned Smart Classrooms & Modern Labs","5-Year MBBS + 12-Month Rotating Internship","20 MD/MS Postgraduate Specialities","Dedicated Research Cell","Anti-Ragging, Ethics, Gender Harassment & Grievance Committees","Multi-Cuisine Restaurants, Staff & Student Housing On Campus"],"departments":[{"name":"M.B.B.S (Bachelor of Medicine, Bachelor of Surgery)","level":"UG"},{"name":"M.D. General Medicine","level":"PG"},{"name":"M.D. Paediatrics","level":"PG"},{"name":"M.D. Anaesthesiology","level":"PG"},{"name":"M.D. Psychiatry","level":"PG"},{"name":"M.D. Dermatology, Venereology & Leprosy","level":"PG"},{"name":"M.D. Radio-Diagnosis","level":"PG"},{"name":"M.D. Emergency Medicine","level":"PG"},{"name":"M.D. Respiratory Medicine","level":"PG"},{"name":"M.S. Otorhinolaryngology (ENT)","level":"PG"},{"name":"M.S. Ophthalmology","level":"PG"},{"name":"M.S. Orthopaedics","level":"PG"},{"name":"M.S. Obstetrics and Gynaecology","level":"PG"},{"name":"M.S. General Surgery","level":"PG"},{"name":"M.D. Anatomy","level":"PG"},{"name":"M.D. Physiology","level":"PG"},{"name":"M.D. Biochemistry","level":"PG"},{"name":"M.D. Pharmacology","level":"PG"},{"name":"M.D. Pathology","level":"PG"},{"name":"M.D. Microbiology","level":"PG"},{"name":"M.D. Forensic Medicine","level":"PG"},{"name":"M.D. Community Medicine","level":"PG"}],"facilities":[{"icon":"ti-cpu","name":"Air-Conditioned Smart Classrooms"},{"icon":"ti-books","name":"Central Library Learning Centre"},{"icon":"ti-flask","name":"Modern Pre-Clinical & Para-Clinical Labs"},{"icon":"ti-heartbeat","name":"Attached Multi-Specialty Teaching Hospital"},{"icon":"ti-home","name":"Student & Staff Housing"},{"icon":"ti-trophy","name":"Playgrounds & Sports Facilities"},{"