('dr-mgr-fisheries-college-and-research-institute-ponneri','dr-mgr-fisheries-college-and-research-institute-ponneri','Dr. M.G.R. Fisheries College and Research Institute, Ponneri','Dr. M.G.R. Fisheries College & Research Institute','fishery','Government Fisheries College and Research Institute','Government','2013','Ponneri','Thiruvallur','Ponneri - 601204, Thiruvallur District, Tamil Nadu, India','https://maps.google.com/?q=Dr.+M.G.R.+Fisheries+College+and+Research+Institute+Ponneri','https://www.tnjfu.ac.in/fcripon/index.php','044-27971556','mailto:deanfcriponneri@tnfu.ac.in','https://collegeshine.com/wp-content/uploads/2026/06/fisheries-college-and-research-institute-thoothukudi.webp','Dr. M.G.R. Fisheries College and Research - CollegeShine','Dr. M.G.R. Fisheries College and Research Institute, Ponneri is a government fishery science college in Ponneri established in 2013. Harnessing the Science.',NULL, '{"id":"dr-mgr-fisheries-college-and-research-institute-ponneri","seo":{"metaTitle":"Dr. M.G.R. Fisheries College and Research - CollegeShine","metaDescription":"Dr. M.G.R. Fisheries College and Research Institute, Ponneri is a government fishery science college in Ponneri established in 2013. Harnessing the Science.","metaKeywords":["Dr. M.G.R. Fisheries College and Research Institute","Ponneri","Dr. M.G.R. Fisheries College & Research Institute","Dr. M.G.R. Fisheries College and Research Institute","Ponneri admission 2026","Dr. M.G.R. Fisheries College and Research Institute","Ponneri fees","Dr. M.G.R. Fisheries College and Research Institute","Ponneri courses","Fishery Science colleges in Thiruvallur","Ponneri","Thiruvallur","Fishery Science","Government","Government Fisheries College and Research Institute","Constituent College of Tamil Nadu Dr.J.Jayalalithaa Fisheries University","Government of Tamil Nadu Institution","UGC Recognized University System","ICAR Academic Framework","B.F.Sc. - Bachelor of Fisheries Science","M.F.Sc. - Fisheries Resource Management","M.F.Sc. - Aquaculture","Ph.D. - Fisheries Sciences"],"canonicalUrl":null,"robots":"index, follow","h1":"Dr. M.G.R. Fisheries College and Research Institute, Ponneri","openGraph":{"title":"Dr. M.G.R. Fisheries College and Research - CollegeShine","description":"Dr. M.G.R. Fisheries College and Research Institute, Ponneri is a government fishery science college in Ponneri established in 2013. Harnessing the Science.","image":"https://collegeshine.com/wp-content/uploads/2026/06/fisheries-college-and-research-institute-thoothukudi.webp","type":"website","url":null},"twitterCard":{"card":"summary_large_image","title":"Dr. M.G.R. Fisheries College and Research - CollegeShine","description":"Dr. M.G.R. Fisheries College and Research Institute, Ponneri is a government fishery science college in Ponneri established in 2013. Harnessing the Science.","image":"https://collegeshine.com/wp-content/uploads/2026/06/fisheries-college-and-research-institute-thoothukudi.webp"},"structuredData":{"schemaType":"CollegeOrUniversity","jsonLd":null,"includeFaqSchema":true,"includeBreadcrumbSchema":true}},"name":"Dr. M.G.R. Fisheries College and Research Institute, Ponneri","shortName":"Dr. M.G.R. Fisheries College & Research Institute","tagline":"Harnessing the Science of Fisheries for Food, Nutrition and Livelihood","category":"fishery","type":"Government Fisheries College and Research Institute","ownership":"Government","established":2013,"location":"Ponneri","district":"Thiruvallur","address":"Ponneri - 601204, Thiruvallur District, Tamil Nadu, India","mapLink":"https://maps.google.com/?q=Dr.+M.G.R.+Fisheries+College+and+Research+Institute+Ponneri","mapQuery":"Dr.+M.G.R.+Fisheries+College+and+Research+Institute+Ponneri","website":"https://www.tnjfu.ac.in/fcripon/index.php","phone":"044-27971556","email":"mailto:deanfcriponneri@tnfu.ac.in","image":"https://collegeshine.com/wp-content/uploads/2026/06/fisheries-college-and-research-institute-thoothukudi.webp","videoUrl":"https://www.youtube.com/embed/N00EXrJZTVc?si=HXizFQ4fHq1KgUE-","affiliation":"Tamil Nadu Dr.J.Jayalalithaa Fisheries University (TNJFU)","accreditation":["Constituent College of Tamil Nadu Dr.J.Jayalalithaa Fisheries University","Government of Tamil Nadu Institution","UGC Recognized University System","ICAR Academic Framework","State Fisheries University Institution"],"about":"Dr. M.G.R. Fisheries College and Research Institute, Ponneri is a constituent fisheries college of Tamil Nadu Dr.J.Jayalalithaa Fisheries University (TNJFU). The institution was formally inaugurated on 20 February 2013 and was established to develop professionally qualified manpower for the fisheries sector and to support fisheries and aquaculture research, extension and entrepreneurship.\\n\\nThe college offers the Bachelor of Fisheries Science (B.F.Sc.) programme and postgraduate and doctoral research opportunities through its specialized departments. Its academic and research activities cover aquaculture, fisheries resource management, fish processing technology, fisheries extension and economics, fishing technology and fisheries engineering, aquatic environment management and aquatic animal health management.\\n\\nThe Ponneri campus has a 62,000 sq.ft. administrative and academic block, smart classrooms, state-of-the-art laboratories for fisheries research and quality testing, a modern fish processing and quality-testing incubation centre, marine aqua workshop facilities, boys and girls hostels with dining facilities and playgrounds. The institution also operates or supports research and instructional farm facilities associated with freshwater, brackishwater and Pulicat aquaculture.","highlights":["Inaugurated on 20 February 2013","Constituent College of TNJFU","Government Fisheries Education Institution","Bachelor of Fisheries Science (B.F.Sc.)","B.F.Sc. Intake of 60 Students Per Year","Postgraduate & Ph.D. Research Opportunities","62,000 sq.ft. Academic & Administrative Block","Smart Classrooms","State-