mission process."},{"title":"Merit / Selection Process","desc":"Admission is processed according to the applicable government and university rules for the selected programme."},{"title":"Fee Payment and Enrollment","desc":"Selected students complete the prescribed fee payment and college enrollment formalities."}],"scholarships":["Government Scholarship of ₹500 per month for 10 months based on attendance","Free Bus Pass for Eligible Students as per Government Rules","Government Welfare Scholarship Support where applicable","Approximate Merit-Based Educational Assistance"],"events":["Music and Cultural Programmes","Classical Music Performances","Bharathanatyam Programmes","Student Cultural Events","Government Cultural Department Events","Music and Fine Arts University Academic Events"],"distanceInfo":{"airport":"Approx. 15 km","railway":"Approx. 15 km","bustand":"Approx. 12 km","metro":"Approx. 15 km","hospital":"Approx. 3 km"},"hostelFeatures":["Approximate Student Accommodation Support","Student Welfare Facilities","Government Welfare Support","Basic Student Amenities","Academic Study Support","Campus Safety Measures","Library Access","Transport Support"],"technicalClubs":["Approximate Music Technology Activities","Digital Learning Activities","Music Research Activities","Academic Technology Support","Audio and Performance Practice"],"culturalClubs":["Vocal Music Activities","Veena Practice Group","Violin Practice Group","Bharathanatyam Activities","Classical Music Performance Group","Traditional Arts Activities"],"communityService":["Government Cultural Awareness Programmes","Traditional Music Promotion","Classical Dance Promotion","Community Cultural Performances","Arts Awareness Activities","Preservation of Tamil Cultural Heritage"]}'),
('tamil-nadu-government-music-college-thiruvaiyaru','tamil-nadu-government-music-college-thiruvaiyaru','Tamil Nadu Government Music College, Thiruvaiyaru','TN Government Music College Thiruvaiyaru','fine-arts','Government Music College','Government','1965','Thiruvaiyaru, Thanjavur','Thanjavur','Tamil Nadu Government Music College, Thiruvaiyaru, Thanjavur District, Tamil Nadu 613204','https://maps.google.com/?q=Tamil+Nadu+Government+Music+College+Thiruvaiyaru','https://artandculture.tn.gov.in/tamil-nadu-government-music-college-thiruvaiyaru','04362-261600','tngmctvyr@gmail.com','https://collegeshine.com/wp-content/uploads/2026/07/TamilNadu-govt-college-collegshine_7_11zon-150x150.webp','Tamil Nadu Government Music College, Thiruvaiyaru - CollegeShine','Tamil Nadu Government Music College, Thiruvaiyaru is a government fine arts & performing arts college in Thiruvaiyaru, Thanjavur established in 1965.',NULL, '{"id":"tamil-nadu-government-music-college-thiruvaiyaru","seo":{"metaTitle":"Tamil Nadu Government Music College, Thiruvaiyaru - CollegeShine","metaDescription":"Tamil Nadu Government Music College, Thiruvaiyaru is a government fine arts & performing arts college in Thiruvaiyaru, Thanjavur established in 1965.","metaKeywords":["Tamil Nadu Government Music College","Thiruvaiyaru","TN Government Music College Thiruvaiyaru","Tamil Nadu Government Music College","Thiruvaiyaru admission 2026","Tamil Nadu Government Music College","Thiruvaiyaru fees","Tamil Nadu Government Music College","Thiruvaiyaru courses","Fine Arts & Performing Arts colleges in Thanjavur","Thiruvaiyaru","Thanjavur","Thanjavur","Fine Arts & Performing Arts","Government","Government Music College","Government of Tamil Nadu Institution","Department of Art and Culture","Government of Tamil Nadu","Affiliated to Tamil Nadu Dr. J. Jayalalithaa Music and Fine Arts University","Diploma in Vocal","Diploma in Veena","Diploma in Violin","Diploma in Nadaswaram","Diploma in Thavil","Diploma in Mridangam"],"canonicalUrl":null,"robots":"index, follow","h1":"Tamil Nadu Government Music College, Thiruvaiyaru","openGraph":{"title":"Tamil Nadu Government Music College, Thiruvaiyaru - CollegeShine","description":"Tamil Nadu Government Music College, Thiruvaiyaru is a government fine arts & performing arts college in Thiruvaiyaru, Thanjavur established in 1965.","image":"https://collegeshine.com/wp-content/uploads/2026/07/TamilNadu-govt-college-collegshine_7_11zon-150x150.webp","type":"website","url":null},"twitterCard":{"card":"summary_large_image","title":"Tamil Nadu Government Music College, Thiruvaiyaru - CollegeShine","description":"Tamil Nadu Government Music College, Thiruvaiyaru is a government fine arts & performing arts college in Thiruvaiyaru, Thanjavur established in 1965.","image":"https://collegeshine.com/wp-content/uploads/2026/07/TamilNadu-govt-college-collegshine_7_11zon-150x150.webp"},"structuredData":{"schemaType":"CollegeOrUniversity","jsonLd":null,"includeFaqSchema":true,"includeBreadcrumbSchema":true}},"name":"Tamil Nadu Government Music College, Thiruvaiyaru","shortName":"TN Government Music College Thiruvaiyaru","tagline":"Preserving and Promoting Tamil Musical Heritage Through Education, Research and Performing Arts","category":"fine-arts","type":"Government Music College","ownership":"Government","established":1965,"location":"Thiruvaiyaru, Thanjavur","district":"Thanjavur","address":"Tamil Nadu Government Music College, Thiruvaiyaru, Thanjavur District, Tamil Nadu 613204","mapLink":"https://maps.google.com/?q=Tamil+Nadu+Government+Music+College+Thiruvaiyaru","mapQuery":"Tamil+Nadu+Government+Music+College+Thiruvaiyaru","website":"https://artandculture.tn.gov.in/tamil-nadu-government-music-college-thiruvaiyaru","phone":"04362-261600","email":"tngmctvyr@gmail.com","image":"https://collegeshine.com/wp-content/uploads/2026/07/TamilNadu-govt-college-collegshine_7_11zon-150x150.webp","videoUrl":"https://www.youtube.com/results?search_query=Tamil+Nadu+Government+Music+College+Thiruvaiyaru","affiliation":"Affiliated to Tamil Nadu Dr. J. Jayalalithaa Music and Fine Arts University","accreditation":["Government of Tamil Nadu Institution","Department of Art and Culture, Government of Tamil Nadu","Affiliated to Tamil Nadu Dr. J. Jayalalithaa Music and Fine Arts University"],"about":"Tamil Nadu Government Music College, Thiruvaiyaru is a government institution dedicated to the preservation, teaching and promotion of music and performing arts, with a strong emphasis on Tamil musical heritage. The institution was established in 1965 as part of Raja''s College under Madras University and was affiliated to Bharathidasan University from 1983. Since 1997, it has functioned under the Department of Art and Culture, Government of Tamil Nadu, as Tamil Nadu Government Music College. The college became affiliated to Tamil Nadu Dr. J. Jayalalithaa Music and Fine Arts University in 2014.\\n\\nThe college is located in Thiruvaiyaru, an important centre of Carnatic music associated with Saint Thyagaraja and the annual Thyagaraja Aradhana. The institution provides Diploma, Post-Diploma, B.A., M.A. and Ph.D. programmes in music and related performing arts. Its academic offerings include Vocal, Veena, Violin, Nadaswaram, Thavil, Mridangam, Bharathanatyam, Folk Dance and Nattuvangam. The college operates from its own 11-acre campus and has separate government-supported boys'' and girls'' hostel facilities. It also maintains a library, placement cell, anti-ragging cell, alumni association and an Earn While You Learn performance initiative.","highlights":["11-Acre Government Music College Campus","Established in 1965","Functioning under Tamil Nadu Department of Art and Culture since 1997","Affiliated to Tamil Nadu Dr. J. Jayalalithaa Music and Fine Arts University","Diploma, UG, PG and Ph.D. Music Programmes","Specialized Training in Vocal, Veena and Violin","Traditional Training in Nadaswaram, Thavil and Mridangam","Bharathanatyam and Folk Dance Training","50-Seat Girls'' Hostel","100-Seat Boys'' Hostel","Full-Fledged Placement Cell","Earn While You Learn Performance Scheme"],"departments":[{"name":"Diploma in Vocal","level":"Diploma"},{"name":"Diploma in Veena","level":"Diploma"},{"name":"Diploma in Violin","level":"Diploma"},{"name":"Diploma in Nadaswaram","level":"Diploma"},{"name":"Diploma in Thavil","level":"Diploma"},{"name":"Diploma in Mridangam","level":"Diploma"},{"name":"Diploma in Bharathanatyam / Folk Dance","level":"Diploma"},{"name":"Diploma in Music Teaching","level":"Diploma"},{"name":"Post Diploma in Nattuvangam","level":"PG"},{"name":"B.A. Music - Vocal","level":"UG"},{"name":"B.A. Music - Veena","level":"UG"},{"name":"B.A. Music - Violin","level":"UG"},{"name":"B.A. Music - Bharathanatyam / Nadaswaram / Thavil","level":"UG"},{"name":"M.A. Music - Vocal / Veena","level":"PG"},{"name":"Ph.D. in Music","level":"PhD"}],"facilities":[{"icon":"ti-books","name":"Well Equipped Music Library"},{"icon":"ti-home","name":"Girls Hostel"},{"icon":"ti-home","name":"Boys Hostel"},{"icon":"ti-microphone","name":"Music Practice Facilities"},{"icon":"ti-music","name":"Vocal Training Facilities"},{"icon":"ti-music","name":"Veena & Violin Training Facilities"},{"icon":"ti-music","name":"Traditional Instrument Training"},{"icon":"ti-heartbeat","name":"Basic Medical Support"},{"icon":"ti-trophy","name":"Sports Facilities"},{"icon":"ti-microphone","name":"Performance & Stage Facilities"},{"icon":"ti-crown","name":"Placement Cell"},{"icon":"ti-medall","name":"Music Research Facilities"}],"placementRate":65,"avgPackage":"₹2.5 LPA","highestPackage":"₹5 LPA","placementYear":null,"admissionProcess":[{"title":"Check Course Eligibility","desc":"Diploma applicants generally require a pass in Standard X; B.A. Music applicants require Standard XII; M.A. Music applicants require a degree in Music."},{"title":"Apply Through the Prescribed Admission Process","desc":"Candidates apply for admission according to the college and Tamil Nadu Music and Fine Arts University admission procedures."},{"title":"Submit Academic and Supporting Documents","desc":"Candidates submit the required educational certificates, identity documents and other documents prescribed for the selected programme."},{"title":"Selection and Seat Allotment","desc":"Eligible candidates are selected according to the applicable government, university and college admission rules."},{"title":"Fee Payment & Enrollment","desc":"Selected candidates pay the prescribed fees and complete the college enrollment and verification process."}],"scholarships":["Government Attendance-Based Scholarship","BC / MBC Welfare Scholarship","SC / ST Welfare Scholarship","Post-Matric Scholarship","Government Scholarship Schemes","Merit-Based Assistance","Attendance-Based Student Scholarship","Free Government Bus Pass for Eligible Students"],"events":["Thyagaraja Aradhana Related Cultural Programmes","Music Concerts","Classical Music Performances","Bharathanatyam Performances","Traditional Instrument Performances","Oral and Community Cultural Awareness Programmes"],"distanceInfo":{"airport":"Approx. 65 km - Tiruchirappalli International Airport","railway":"Approx. 15 km - Thanjavur Railway Station","bustand":"Approx. 1 km - Thiruvaiyaru Bus Stand","metro":"Approx. 300 km - Nearest Metro Rail service in Chennai","hospital":"Approx. 1 km - Nearby Government/Local Hospital"},"hostelFeatures":["50-Seat Girls Hostel","100-Seat Boys Hostel","Government-Supported Hostel Facilities","Hostel Accommodation for Eligible Students","Mess / Food Facility","Basic Student Welfare Support","Study Space","Residential Student Support"],"technicalClubs":["Music Research Activities","Vocal Practice Group","Veena Practice Group","Violin Practice Group","Traditional Instrument Practice Group"],"culturalClubs":["Carnatic Music Activities","Bharathanatyam Activities","Folk Dance Activities","Traditional Instrument Performance Group","Music Concert Group"],"communityService"